/**
 * doGet using Typescript as the processing pipeline
 * @param ac
 */
export async function doGet(ac) {
    const stream = ac.clientService.doGet(ac.ticket, {});
    const collector = new IPCCollector();
    stream.on('data', (msg) => {
        const header = msg.getDataHeader_asU8?.();
        const body = msg.getDataBody_asU8?.();
        // Reassemble IPC correctly: frame *header*, append *raw* body (+pad)
        collector.add(header, body);
    });
    stream.on('end', () => {
        try {
            const table = collector.toTable();
            // Felder typisiert lesen (TS7006 vermeiden)
            const fields = table.schema.fields;
            console.log('schema fields:', fields.map((f) => f.name));
            const lonField = fields.findIndex((f) => /^(lon|longitude|x)$/i.test(f.name));
            const latField = fields.findIndex((f) => /^(lat|latitude|y)$/i.test(f.name));
            if (lonField < 0 || latField < 0) {
                console.warn('Could not auto-detect lon/lat columns. Schema fields:', fields.map((f) => f.name));
                return;
            }
            const lon = table.getChildAt(lonField).toArray();
            const lat = table.getChildAt(latField).toArray();
            const host = document.getElementById('spinningGlobe');
            startGlobeScatter({ container: host, lon, lat });
        }
        catch (e) {
            console.error('Failed to parse IPC / render globe:', e);
        }
        finally {
            console.log("Stream has ended");
        }
        // save dataset to SAB
        if (!dumpChunksToSAB(ac.sarb, collector.parts))
            console.warn("Failed to save the collector to memory.");
    });
    stream.on('error', (err) => {
        console.error('DoGet stream error: ', err);
    });
}
